import pandas as pd
import json
import os

def calculate_rc7():
    # 1. Load your 2026 season data file generated by pull_season.py
    csv_file = "games_season.csv" # Update to match your scraper's output filename
    
    if not os.path.exists(csv_file):
        print(f"Error: {csv_file} not found. Ensure pull_season.py runs first.")
        return

    df = pd.read_csv(csv_file)

    # 2. Ensure numerical columns are clean
    stat_cols = ['AB', 'H', 'BB', '2B', '3B', 'HR']
    for col in stat_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce').fillna(0)

    # 3. Aggregate stats by player for the full 2026 season
    # (Adjust 'player_name' / 'team' column names if yours are named differently)
    player_stats = df.groupby(['player_name', 'team']).agg({
        'game_id': 'nunique',
        'AB': 'sum',
        'H': 'sum',
        'BB': 'sum',
        '2B': 'sum',
        '3B': 'sum',
        'HR': 'sum'
    }).reset_index()

    player_stats.rename(columns={'game_id': 'games_played'}, inplace=True)

    # 4. Calculate Total Bases, Plate Appearances, and Outs
    player_stats['TB'] = (
        player_stats['H'] + 
        player_stats['2B'] + 
        (2 * player_stats['3B']) + 
        (3 * player_stats['HR'])
    )
    player_stats['PA'] = player_stats['AB'] + player_stats['BB']
    player_stats['Outs'] = player_stats['AB'] - player_stats['H']

    # 5. Bill James Classic RC & Raw RC7
    # RC = ((H + BB) * TB) / (AB + BB)
    player_stats['RC'] = player_stats.apply(
        lambda r: ((r['H'] + r['BB']) * r['TB']) / r['PA'] if r['PA'] > 0 else 0, axis=1
    )
    
    # Raw RC per 21 outs (7 innings)
    player_stats['RC7_raw'] = player_stats.apply(
        lambda r: (r['RC'] / r['Outs']) * 21 if r['Outs'] > 0 else 0, axis=1
    )

    # 6. Apply Minimum PA Filter (e.g., 30 PA for full season qualification)
    qualified_players = player_stats[player_stats['PA'] >= 30].copy()

    # 7. Neutral OPAF Fallback Baseline (1.00)
    # If opponent pitching metrics are available in your CSV, insert scaling here
    qualified_players['OPAF'] = 1.00
    qualified_players['RC7_adj'] = (qualified_players['RC7_raw'] * qualified_players['OPAF']).round(2)
    qualified_players['RC7_raw'] = qualified_players['RC7_raw'].round(2)

    # 8. Format Output
    output_df = qualified_players[[
        'player_name', 'team', 'games_played', 'PA', 'AB', 'H', 'HR', 'RC7_raw', 'OPAF', 'RC7_adj'
    ]].sort_values(by='RC7_adj', ascending=False)

    # 9. Output to players.json
    output_df.to_dict(orient='records')
    with open('players.json', 'w') as f:
        json.dump(output_df.to_dict(orient='records'), f, indent=2)

    print(f"Successfully calculated RC7/adj for {len(output_df)} qualified players for 2026!")

if __name__ == "__main__":
    calculate_rc7()
